-- Ejecutar una vez en Supabase > SQL Editor.
create extension if not exists pgcrypto;
do $$ begin create type public.request_status as enum ('pending','accepted','next','playing','played','rejected'); exception when duplicate_object then null; end $$;
create table if not exists public.events (id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null,slug text not null unique check(slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),event_date timestamptz,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.song_requests (id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,title text not null check(char_length(title) between 1 and 120),artist text check(char_length(artist)<=120),requester_name text check(char_length(requester_name)<=80),message text check(char_length(message)<=240),votes integer not null default 1 check(votes>=1),status public.request_status not null default 'pending',created_at timestamptz not null default now());
create table if not exists public.song_votes (request_id uuid not null references public.song_requests(id) on delete cascade,voter_hash text not null,created_at timestamptz not null default now(),primary key(request_id,voter_hash));
create index if not exists song_requests_event_votes_idx on public.song_requests(event_id,votes desc);
alter table public.events enable row level security;alter table public.song_requests enable row level security;alter table public.song_votes enable row level security;
revoke all on public.events,public.song_requests,public.song_votes from anon,authenticated;
grant select on public.events to anon,authenticated;grant select on public.song_requests to anon,authenticated;grant update,delete on public.song_requests to authenticated;
drop policy if exists "active events public read" on public.events;create policy "active events public read" on public.events for select to anon,authenticated using(is_active=true or owner_id=auth.uid());
drop policy if exists "owner manages event" on public.events;create policy "owner manages event" on public.events for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
drop policy if exists "public reads active event requests" on public.song_requests;create policy "public reads active event requests" on public.song_requests for select to anon,authenticated using(exists(select 1 from public.events e where e.id=event_id and (e.is_active or e.owner_id=auth.uid())));
drop policy if exists "owner manages requests" on public.song_requests;create policy "owner manages requests" on public.song_requests for update to authenticated using(exists(select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid())) with check(exists(select 1 from public.events e where e.id=event_id and e.owner_id=auth.uid()));
create or replace function public.create_song_request(event_id uuid,title text,artist text default null,requester_name text default null,message text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; clean_title text:=trim(title); begin if not exists(select 1 from events e where e.id=event_id and e.is_active) then raise exception 'event_inactive'; end if;if exists(select 1 from song_requests r where r.event_id=create_song_request.event_id and r.status not in ('played','rejected') and lower(trim(r.title))=lower(clean_title) and lower(trim(coalesce(r.artist,'')))=lower(trim(coalesce(create_song_request.artist,'')))) then raise exception 'duplicate_song';end if;insert into song_requests(event_id,title,artist,requester_name,message) values(event_id,clean_title,nullif(trim(artist),''),nullif(trim(requester_name),''),nullif(trim(message),'')) returning id into new_id;return new_id;end $$;
create or replace function public.vote_song(request_id uuid,voter_token text) returns void language plpgsql security definer set search_path=public as $$ declare vh text:=encode(digest(voter_token,'sha256'),'hex'); begin if char_length(voter_token)<32 then raise exception 'invalid_voter';end if;insert into song_votes(request_id,voter_hash) select request_id,vh where exists(select 1 from song_requests r join events e on e.id=r.event_id where r.id=request_id and e.is_active);if not found then raise exception 'event_inactive';end if;update song_requests set votes=votes+1 where id=request_id;exception when unique_violation then raise exception 'duplicate_vote';end $$;
revoke all on function public.create_song_request(uuid,text,text,text,text) from public;revoke all on function public.vote_song(uuid,text) from public;grant execute on function public.create_song_request(uuid,text,text,text,text) to anon,authenticated;grant execute on function public.vote_song(uuid,text) to anon,authenticated;
do $$ begin alter publication supabase_realtime add table public.song_requests; exception when duplicate_object then null; end $$;
